from collections import defaultdict

def match_offsets(a,b):
    counts=defaultdict(list)
    # translate b by t to overlap a markers
    for ma in markers[a]:
        for mb in markers[b]:
            t=(ma[0]-mb[0],ma[1]-mb[1])
            counts[t].append((ma,mb))
    return sorted(((len(v),t,v) for t,v in counts.items()), reverse=True)
