from collections import deque

def comps(mat):
    H,W=len(mat),len(mat[0]); seen=set(); out=[]
    for r in range(H):
      for c in range(W):
        v=mat[r][c]
        if v==0 or v==2 or (r,c) in seen: continue
        q=[(r,c)]; seen.add((r,c)); cells=[]
        while q:
          p=q.pop(); cells.append(p)
          for dr,dc in ((1,0),(-1,0),(0,1),(0,-1)):
            np=(p[0]+dr,p[1]+dc)
            if 0<=np[0]<H and 0<=np[1]<W and np not in seen and mat[np[0]][np[1]]==v:
              seen.add(np); q.append(np)
        rs=[p[0] for p in cells]; cs=[p[1] for p in cells]
        out.append((v,(min(rs),min(cs),max(rs),max(cs)),cells))
    return out
